// The contents of this file are heavily based on the audio-support.ts file since the systems
// are have very similar requirements. In the future we might want to refactor to share more code
// between them, but for now I'm keeping them separate since there are some differences (like VFX
// need info on where on the screen to play) and to avoid over-engineering a shared solution
// until we have more use cases and better understand the commonalities and differences between the systems.

import { createContext, createSignal, useContext, type Accessor } from "solid-js";

import { UiVfx } from "#core/ui/vfx/vfx-manager.js";
import { asyncLoad } from "#core/ui-next/utilities/async-load.js";

import vfxBaseRulesUrl from "#core/ui-next/vfx-rules.json?url";

export type VfxRuleConstraint =
	| string
	| { op: undefined; value: string }
	| { op: "eq" | "neq"; value: string | number | null }
	| { op: "eq" | "neq" | "lt" | "lte" | "gt" | "gte" | "exists"; value: string | number }
	| { op: "in"; value: string[] };

export interface VfxRule {
	constraints?: Record<string, VfxRuleConstraint>;
	events: Record<string, string>;
	path: string;
}

export interface CompiledVfxRule {
	constraints?: Record<string, VfxRuleConstraint>;
	events: Record<string, string>;
	path: string;
}
export interface CompiledVfxRuleNode {
	rules: CompiledVfxRule[];
	children: Record<string, CompiledVfxRuleNode>;
}

export type VfxEventName =
	| "activate"
	| "dragReleased"
	| "dropAccept"
	| "dropReject"
	| "press"
	| "pressError"
	| "focus"
	| "focusLost"
	| string;

/**
 * Ensure path meets the following criteria:
 * * Segments use only alphanumeric, underscore, or dash. `[azAZ19_-]`.
 * * Segments are separated by forward slashes '/'.
 * * Variables are specified at the end of the path.
 * * Variables consist of alphanumeric, underscore, or dash characters `[azAZ19_-]`.
 * * Multiple variables are joined with ampersand &.
 * * Only 1 set of variables can be defined for a given path.
 * @param path
 */
function _validateVfxRulePath(_path: string) {
	//TODO
	return true;
}

export function compileVfxRules(rules: VfxRule[]) {
	const tree: CompiledVfxRuleNode = {
		rules: [],
		children: {},
	};

	// Reverse to ensure the last rules in the list get higher priority since we find the first match when triggering.
	const reverse = rules.reverse();

	for (const rule of reverse) {
		const segments = rule.path.split("/");

		let current = tree;
		for (const s of segments) {
			let child = current.children[s];

			if (child == null) {
				child = { rules: [], children: {} };
				current.children[s] = child;
			}

			current = child;
		}
		current.rules.push(rule);

		// INVESTIGATE - Do we need to sort the rules in some way (priority? specificity?)
	}

	return tree;
}

interface VfxContextValue {
	path: Accessor<string>;
	vars: Accessor<Record<string, string>>;
	tree: Accessor<CompiledVfxRuleNode>;
}

const [globalRules, setGlobalRules] = createSignal<CompiledVfxRuleNode>({ rules: [], children: {} });

export const VfxContext = createContext<VfxContextValue>({
	path: () => "",
	vars: () => ({}),
	tree: globalRules,
});

function meetsConstraint(key: string, constraint: VfxRuleConstraint, vars: Record<string, string>) {
	if (typeof constraint == "string") {
		return vars[key] == constraint;
	} else {
		if (constraint.op == null) {
			return vars[key] == constraint.value;
		} else {
			switch (constraint.op) {
				case "eq":
					return vars[key] == constraint.value;
					break;
				case "neq":
					return vars[key] != constraint.value;
					break;
				case "lt":
					return constraint.value != null ? vars[key] < constraint.value : false;
					break;
				case "lte":
					return constraint.value != null ? vars[key] <= constraint.value : false;
					break;
				case "gt":
					return constraint.value != null ? vars[key] > constraint.value : false;
					break;
				case "gte":
					return constraint.value != null ? vars[key] >= constraint.value : false;
					break;
				case "exists":
					return vars[key] != null;
					break;
				case "in":
					return constraint.value.includes(vars[key]);
					break;
				default:
					// Invalid operation!
					return false;
			}
		}
	}
}

function meetsConstraints(rule: CompiledVfxRule, vars: Record<string, string>, shouldLogVerbose?: UIDebugWidgetValue) {
	const constraints = rule.constraints;
	if (constraints == null) {
		return true;
	} else {
		return Object.entries(constraints).every(([key, value]) => {
			const result = meetsConstraint(key, value, vars);
			if (shouldLogVerbose != null && shouldLogVerbose) {
				console.log(
					`-- Constraint ${key} ${typeof value === "string" ? "eq" : value.op} ${typeof value === "string" ? value : value.value} -> ${result}`,
				);
			}
			return result;
		});
	}
}

const vfxVariableRegex = /{(\w+)}/g;
export const useVfx = (localSegment?: string) => {
	const ctx = useContext(VfxContext);

	const trigger = (
		segmentOrEventName: string | VfxEventName,
		controlRect: DOMRect,
		eventNameOrVars?: VfxEventName | Record<string, string>,
		optionalVars?: Record<string, string>,
	) => {
		const segment = typeof eventNameOrVars === "string" ? segmentOrEventName : null;
		const eventName = typeof eventNameOrVars === "string" ? eventNameOrVars : segmentOrEventName;
		const localVars = typeof eventNameOrVars === "object" ? eventNameOrVars : optionalVars;

		const path = ctx.path();
		const vars = localVars != null ? { ...ctx.vars(), ...localVars } : ctx.vars();

		// Determine the target path
		const targetPath = [path, localSegment, segment].filter((p) => p).join("/");
		const segments = targetPath.split("/");
		// Walk the Tree
		let current = ctx.tree();
		for (const seg of segments) {
			if (current.children[seg]) {
				current = current.children[seg];
			} else {
				// This condition would occur if the UI is providing more context than what the vfx rules define.
				// For example, if the rules only define "Button" but the UI is triggering "Button/Contextual", then
				// we would hit this condition. In this case, we should stop looking for more specific matches and
				// just evaluate the rules at the current level since they may be designed to be generic enough to handle various contexts.
			}
		}

		const shouldLogVerbose = UI.Debug.getWidgetValue("logVfxRuleConstraintMatching");

		// Find the first match that meets the constraints (assuming rules is descending order!)
		const match = current.rules.find((r) => meetsConstraints(r, vars, shouldLogVerbose));

		if (match?.events[eventName]) {
			const vfx = match.events[eventName];

			// Resolve dynamic templates like "play-button-{leader}" -> "play-button-LEADER_ADA_LOVELACE"
			const tag = vfx.replace(vfxVariableRegex, (_, k) => vars[k] || k);

			const shouldLog = UI.Debug.getWidgetValue("logMatchedVfxTriggers");
			if (shouldLog != null && shouldLog) {
				const strVars = Object.entries(vars)
					.map((entry) => `${entry[0]}=${entry[1]}`)
					.join("&");

				console.log(`${targetPath}[${strVars}]:${eventName} -> ${tag} (${match.path})`);
			}

			if (tag != null && tag != "") {
				UiVfx.triggerScreenVFXToRect(tag, controlRect);
			}
		} else {
			const shouldLog = UI.Debug.getWidgetValue("logUnmatchedVfxTriggers");
			if (shouldLog != null && shouldLog) {
				const strVars = Object.entries(vars)
					.map((entry) => `${entry[0]}=${entry[1]}`)
					.join("&");

				console.log(`${targetPath}[${strVars}]:${eventName} -> No Match`);
			}
		}
	};

	return trigger;
};

// #region Load Global VFX Rules
engine.whenReady.then(async () => {
	// For now we're hardcoding the path to the vfx rules json file until we have the modding
	// framework be able to provide them.
	//const vfxRules = Modding.getVfxRulesUrls();
	const vfxRules = vfxBaseRulesUrl ? [vfxBaseRulesUrl] : [];

	const rules = (await Promise.all(vfxRules.map(asyncLoad))).flatMap((result) => JSON.parse(result) as VfxRule[]);
	setGlobalRules(compileVfxRules(rules));
});
// #endregion

